import {CONFIG} from '../data/config.js';import {EVENTS} from '../data/events.js';import {income,spend,addXP} from '../core/game.js';
export function nextEvent(s){if(s.level<4||s.event!==null||s.playtime-s.lastEvent<CONFIG.eventInterval)return false;const unseen=EVENTS.filter(e=>!s.eventSeen.includes(e.id));if(!unseen.length)return false;const event=unseen[Math.floor(Math.random()*unseen.length)];s.event=event.id;s.lastEvent=s.playtime;return true;}
export function resolveEvent(s,choice){const e=EVENTS[s.event];if(!e||!['try','safe'].includes(choice))return {ok:false,reason:'invalid'};if(choice==='try'){if(!spend(s,Math.round(income(s)*e.costSeconds)))return {ok:false,reason:'money'};s.skills[e.skill]=Math.min(100,s.skills[e.skill]+1);addXP(s,e.rewardXP);}else addXP(s,e.safeXP);s.eventSeen.push(e.id);s.event=null;return {ok:true};}
